import React, { useState, useEffect } from 'react';
import { GoogleGenerativeAI } from "@google/generative-ai";

function App() {
  // ⚠️ API KEY'İNİ BURAYA YAPIŞTIR
  const API_KEY = "BURAYA_GOOGLE_API_KEY_YAPISTIR"; 

  const [mekanlar, setMekanlar] = useState([]);
  const [favoriler, setFavoriler] = useState([]); 
  const [filtre, setFiltre] = useState('Hepsi');
  const [maxSure, setMaxSure] = useState('');

  const [seciliMekan, setSeciliMekan] = useState(null); 
  const [listeAcik, setListeAcik] = useState(false);
  const [aktifResimIndex, setAktifResimIndex] = useState(0);

  // AI Durumları
  const [aiCevap, setAiCevap] = useState("");
  const [aiYukleniyor, setAiYukleniyor] = useState(false);
  const [aiDil, setAiDil] = useState("Türkçe");

  // Veri Çekme
  useEffect(() => {
    fetch('http://localhost:5000/api/rota')
      .then(res => res.json())
      .then(data => setMekanlar(Array.isArray(data) ? data : []))
      .catch(err => console.error("Bağlantı Hatası: Lütfen backend servisinin çalıştığından emin olun.", err));
  }, []);

  // --- ROTA EKLE / ÇIKAR (Düzeltildi) ---
  const favoriEkleCikar = (mekan) => {
    setFavoriler((prev) => {
      // ID'leri sayıya çevirerek karşılaştırıyoruz (Daha güvenli)
      const varMi = prev.some(item => Number(item.id) === Number(mekan.id));

      if (varMi) {
        return prev.filter(item => Number(item.id) !== Number(mekan.id));
      } else {
        // Süreyi sayıya çevirerek ekliyoruz
        return [...prev, { ...mekan, sure: parseInt(mekan.sure, 10) || 0 }];
      }
    });
  };

  // --- DETAY AÇMA ---
  const detayAc = (mekan) => {
    const guvenliMekan = { 
      ...mekan, 
      resimler: (mekan.resimler && mekan.resimler.length > 0) ? mekan.resimler : ["https://via.placeholder.com/400"] 
    };
    setSeciliMekan(guvenliMekan); 
    setAktifResimIndex(0); 
    setAiCevap(""); 
  };

  // --- HESAPLAMALAR (Düzeltildi) ---
  const toplamSure = favoriler.reduce((toplam, m) => toplam + (parseInt(m.sure, 10) || 0), 0);
  const saat = Math.floor(toplamSure / 60);
  const dakika = toplamSure % 60;

  // AI Fonksiyonu
  const yapayZekayaSor = async (mekanAdi, bolge) => {
    if (!API_KEY || API_KEY.includes("BURAYA")) {
      setAiCevap("⚠️ Lütfen geçerli bir API Key yerleştirin.");
      return;
    }
    setAiYukleniyor(true);
    setAiCevap(""); 
    try {
      const genAI = new GoogleGenerativeAI(API_KEY);
      const model = genAI.getGenerativeModel({ model: "gemini-1.5-flash"});
      const prompt = `Sen Antalya rehberisin. "${mekanAdi}" (${bolge}) hakkında ${aiDil} dilinde kısa ve ilgi çekici 3 cümlelik bilgi ver.`;
      const result = await model.generateContent(prompt);
      const response = await result.response;
      setAiCevap(response.text());
    } catch (error) {
      setAiCevap("😔 AI şu an yanıt veremiyor. Anahtarı kontrol edin.");
    } finally {
      setAiYukleniyor(false);
    }
  };

  // Filtreleme Mantığı
  const filtrelenmis = mekanlar.filter(m => {
    const katUygun = filtre === 'Hepsi' || m.kategori === filtre;
    const sureUygun = maxSure === '' || (parseInt(m.sure, 10) || 0) <= parseInt(maxSure, 10);
    return katUygun && sureUygun;
  });

  return (
    <div className="container">
      <style>{`
        body { font-family: 'Poppins', sans-serif; background-color: #f8f9fa; margin: 0; padding: 20px; }
        .header { text-align: center; margin-bottom: 30px; color: #1a4d6e; }
        .controls { display: flex; justify-content: center; gap: 10px; margin-bottom: 25px; flex-wrap: wrap; }
        .summary-bar { 
          background: #1a4d6e; color: white; padding: 15px 30px; 
          border-radius: 50px; display: flex; justify-content: space-around; 
          margin-bottom: 30px; font-weight: 600; cursor: pointer; user-select: none;
          box-shadow: 0 4px 15px rgba(26, 77, 110, 0.3); transition: transform 0.2s;
        }
        .summary-bar:hover { background: #22608a; }
        .grid { display: flex; flex-wrap: wrap; justify-content: center; gap: 25px; }
        .card { width: 280px; background: white; border-radius: 20px; overflow: hidden; box-shadow: 0 5px 15px rgba(0,0,0,0.05); display: flex; flex-direction: column; transition: all 0.3s ease; border: 2px solid transparent; }
        .card:hover { transform: translateY(-5px); border-color: #00c2cb; }
        .card-clickable { cursor: pointer; } 
        .card-image-container { height: 180px; position: relative; padding: 10px; }
        .card-img { width: 100%; height: 100%; object-fit: cover; border-radius: 15px; }
        .badge { position: absolute; top: 15px; right: 15px; background: rgba(0,0,0,0.6); color: white; padding: 4px 10px; border-radius: 8px; font-size: 11px; }
        .btn-action { 
          width: 100%; padding: 10px; border-radius: 20px; border: 1px solid #1a4d6e; 
          background: transparent; color: #1a4d6e; font-weight: 600; cursor: pointer; 
          margin-top: 10px; display: flex; justify-content: center; align-items: center; gap: 5px; 
        }
        .btn-action:hover { background: #1a4d6e; color: white; }
        .btn-remove { border-color: #e74c3c; color: #e74c3c; }
        .btn-remove:hover { background: #e74c3c; color: white; }
        .modal-overlay { position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.8); z-index: 1000; display: flex; justify-content: center; align-items: center; }
        .modal-content { background: white; padding: 25px; border-radius: 20px; max-width: 500px; width: 90%; text-align: center; position: relative; max-height: 90vh; overflow-y: auto; }
        .close-btn { position: absolute; top: 15px; right: 15px; background: #eee; border: none; width: 30px; height: 30px; border-radius: 50%; cursor: pointer; }
        .main-gallery-img { width: 100%; height: 250px; object-fit: cover; border-radius: 15px; }
        .thumbnail-container { display: flex; gap: 10px; margin-top: 15px; overflow-x: auto; justify-content: center; }
        .thumbnail-img { width: 60px; height: 40px; object-fit: cover; border-radius: 8px; cursor: pointer; border: 2px solid transparent; }
        .thumbnail-img.active { border-color: #00c2cb; }
        .ai-box { margin-top: 20px; background: #f0fdfa; padding: 15px; border-radius: 15px; border: 1px dashed #00c2cb; text-align: left; line-height: 1.5; }
      `}</style>

      <div className="header"><h1>🌴 Antalya Rota Asistanı</h1></div>

      <div className="controls">
        <input 
          type="number" 
          placeholder="Maks. Süre (dk)" 
          value={maxSure} 
          onChange={(e) => setMaxSure(e.target.value)} 
          style={{padding: '10px 20px', borderRadius: '25px', border: '1px solid #ddd'}} 
        />
        {['Hepsi', 'Tarih', 'Doğa', 'Yemek', 'Eğlence'].map(k => (
          <button 
            key={k} 
            onClick={() => setFiltre(k)} 
            style={{padding: '8px 20px', borderRadius: '25px', border: 'none', cursor: 'pointer', background: filtre === k ? '#1a4d6e' : 'white', color: filtre === k ? 'white' : '#666', marginLeft: '5px', boxShadow: '0 2px 5px rgba(0,0,0,0.1)'}}
          >
            {k}
          </button>
        ))}
      </div>

      {/* ROTA ÖZET ÇUBUĞU */}
      <div className="summary-bar" onClick={() => setListeAcik(true)}>
        <span>🎒 Rotam: {favoriler.length} Yer</span>
        <span>⏱️ Toplam: {saat > 0 ? `${saat} sa ` : ''}{dakika} dk</span>
      </div>

      <div className="grid">
        {filtrelenmis.map(m => {
          // ID karşılaştırması Number ile yapılıyor
          const seciliMi = favoriler.some(f => Number(f.id) === Number(m.id));
          const anaResim = (m.resimler && m.resimler.length > 0) ? m.resimler[0] : "https://via.placeholder.com/300";

          return (
            <div key={m.id} className="card">
              <div className="card-clickable" onClick={() => detayAc(m)}>
                <div className="card-image-container">
                  <img src={anaResim} alt={m.ad} className="card-img" />
                  <span className="badge">{m.kategori}</span>
                </div>
                <div className="card-content" style={{padding: '0 15px'}}>
                  <h3 style={{margin: '0 0 5px 0', color: '#1a4d6e', fontSize: '16px'}}>{m.ad}</h3>
                  <div style={{fontSize: '13px', color: '#7f8c8d', display: 'flex', justifyContent: 'space-between'}}>
                     <span>📍 {m.bolge}</span><span>⏳ {m.sure} dk</span>
                  </div>
                </div>
              </div>

              <div style={{padding: '15px'}}>
                <button 
                  className={`btn-action ${seciliMi ? 'btn-remove' : ''}`} 
                  onClick={() => favoriEkleCikar(m)}
                >
                  {seciliMi ? 'Rotadan Çıkar ✕' : 'Rotaya Ekle ➜'}
                </button>
              </div>
            </div>
          );
        })}
      </div>

      {/* MEKAN DETAY MODAL */}
      {seciliMekan && (
        <div className="modal-overlay" onClick={() => setSeciliMekan(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={() => setSeciliMekan(null)}>✕</button>
            <img src={seciliMekan.resimler[aktifResimIndex]} className="main-gallery-img" alt="Mekan" />

            {seciliMekan.resimler.length > 1 && (
              <div className="thumbnail-container">
                {seciliMekan.resimler.map((resim, index) => (
                  <img 
                    key={index} 
                    src={resim} 
                    className={`thumbnail-img ${index === aktifResimIndex ? 'active' : ''}`} 
                    onClick={() => setAktifResimIndex(index)} 
                  />
                ))}
              </div>
            )}

            <h2 style={{color: '#1a4d6e', marginTop: '15px'}}>{seciliMekan.ad}</h2>
            <p>📍 {seciliMekan.bolge} | ⏳ Ortalama Ziyaret: {seciliMekan.sure} dk</p>

            <div style={{display:'flex', gap:'10px', justifyContent:'center', marginTop:'15px'}}>
               <select value={aiDil} onChange={(e) => setAiDil(e.target.value)} style={{padding:'8px', borderRadius:'10px', border:'1px solid #ddd'}}>
                  <option>Türkçe</option><option>İngilizce</option><option>Almanca</option>
               </select>
               <button 
                 className="btn-ai" 
                 onClick={() => yapayZekayaSor(seciliMekan.ad, seciliMekan.bolge)} 
                 disabled={aiYukleniyor}
                 style={{background: 'linear-gradient(45deg, #00c2cb, #1a4d6e)', color: 'white', border: 'none', padding: '8px 20px', borderRadius: '10px', cursor: 'pointer', fontWeight: 'bold'}}
               >
                 {aiYukleniyor ? "🤔 Düşünüyorum..." : "🤖 Bilgi Al"}
               </button>
            </div>
            {aiCevap && <div className="ai-box">{aiCevap}</div>}
          </div>
        </div>
      )}

      {/* ROTA LİSTESİ MODAL */}
      {listeAcik && (
        <div className="modal-overlay" onClick={() => setListeAcik(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={() => setListeAcik(false)}>✕</button>
            <h3 style={{color: '#1a4d6e'}}>🎒 Günlük Rotan</h3>
            <hr />
            {favoriler.length === 0 ? <p>Henüz bir yer eklemedin.</p> : (
              favoriler.map(fav => (
                <div key={fav.id} style={{padding: '12px', borderBottom: '1px solid #eee', display: 'flex', justifyContent: 'space-between', alignItems: 'center'}}>
                  <div style={{textAlign:'left'}}>
                    <strong style={{color: '#333'}}>{fav.ad}</strong>
                    <div style={{fontSize:'12px', color:'#777'}}>{fav.bolge} • {fav.sure} dk</div>
                  </div>
                  <button onClick={() => favoriEkleCikar(fav)} style={{background:'#ffebee', color:'#e74c3c', border:'none', borderRadius:'50%', width:'30px', height:'30px', cursor:'pointer', fontWeight:'bold'}}>✕</button>
                </div>
              ))
            )}
            {favoriler.length > 0 && (
              <div style={{marginTop: '20px', padding: '15px', background: '#f8f9fa', borderRadius: '10px'}}>
                <span style={{fontWeight:'bold', color:'#1a4d6e', fontSize: '18px'}}>
                  Toplam Süre: {saat} sa {dakika} dk
                </span>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default App;
